    "<div class=\"tools\"><input id=\"search\" type=\"search\" aria-label=\"\u641c\u7d22\u670d\u52a1\u5546\u6216\u8d26\u53f7\" placeholder=\"\u641c\u7d22\u670d\u52a1\u5546\u6216\u8d26\u53f7\"><button type=\"button\" id=\"refresh\">\u5237\u65b0\u8d26\u53f7</button></div><div class=\"panel\" id=\"accountList\"><div class=\"empty\">\u8fde\u63a5\u5e76\u89e3\u9501\u8bbe\u5907\u540e\u67e5\u770b\u8d26\u53f7</div></div>\n"
    "<details class=\"panel\" id=\"accountEditor\"><summary id=\"editorTitle\">\u6dfb\u52a0\u4ee4\u724c</summary><form id=\"accountForm\"><fieldset id=\"accountFields\" disabled><div class=\"form-grid\"><div><label for=\"issuer\">\u670d\u52a1\u5546</label><input id=\"issuer\" maxlength=\"31\" required autocomplete=\"off\"></div><div><label for=\"account\">\u8d26\u53f7\u540d\u79f0</label><input id=\"account\" maxlength=\"31\" required autocomplete=\"off\"></div><div><label for=\"algorithm\">\u7b97\u6cd5 / \u7c7b\u578b</label><select id=\"algorithm\"><option value=\"0\">TOTP \u00b7 SHA-1</option><option value=\"1\">TOTP \u00b7 SHA-256</option><option value=\"2\">TOTP \u00b7 SHA-512</option><option value=\"3\">Steam Guard</option></select></div><div><label for=\"digits\">\u9a8c\u8bc1\u7801\u4f4d\u6570</label><select id=\"digits\"><option value=\"6\">6 \u4f4d</option><option value=\"8\">8 \u4f4d</option><option value=\"5\" hidden>Steam 5 \u5b57\u7b26</option></select></div><div><label for=\"period\">\u5237\u65b0\u5468\u671f\uff08\u79d2\uff09</label><input id=\"period\" type=\"number\" min=\"1\" max=\"255\" value=\"30\" required></div><div><label for=\"encoding\">\u5bc6\u94a5\u7f16\u7801</label><select id=\"encoding\"><option value=\"base32\">Base32</option><option value=\"base64\">Steam shared_secret \u00b7 Base64</option></select></div><div class=\"full\"><label for=\"secret\">\u5bc6\u94a5 <span id=\"secretHint\" class=\"muted\">\uff08\u4ec5\u5728\u6dfb\u52a0\u6216\u66f4\u6362\u65f6\u586b\u5199\uff09</span></label><input id=\"secret\" type=\"password\" autocomplete=\"new-password\" spellcheck=\"false\" maxlength=\"256\"><p class=\"hint\">\u7f16\u8f91\u65f6\u7559\u7a7a\u4fdd\u7559\u539f\u5bc6\u94a5\u3002Steam \u4f7f\u7528\u4f60\u5df2\u5408\u6cd5\u6301\u6709\u7684 shared_secret\uff1b\u4e0d\u9700\u8981\u5bc6\u7801\u3001\u767b\u5f55 cookie \u6216 identity_secret\u3002</p></div></div><div class=\"row\"><button class=\"primary\" id=\"saveAccount\" type=\"submit\">\u4fdd\u5b58\u4ee4\u724c</button><button id=\"cancelEdit\" type=\"button\">\u53d6\u6d88\u7f16\u8f91</button></div></fieldset></form></details>\n"
    "<details class=\"panel\"><summary>\u5bfc\u5165 otpauth URI</summary><form id=\"importForm\"><fieldset id=\"importFields\" disabled><label for=\"uris\">\u6bcf\u884c\u4e00\u6761 otpauth://totp/ \u94fe\u63a5</label><textarea id=\"uris\" spellcheck=\"false\" autocomplete=\"off\" placeholder=\"\u7c98\u8d34\u5df2\u6709\u7684 otpauth URI\uff0c\u4e0d\u4f1a\u4e0a\u4f20\u5230\u7b2c\u4e09\u65b9\"></textarea><p class=\"hint\">\u652f\u6301 SHA1 / SHA256 / SHA512\u3001\u4f4d\u6570\u4e0e\u5468\u671f\u53c2\u6570\u3002Steam \u94fe\u63a5\u53ef\u5e26 encoder=steam\u3002\u5bfc\u5165\u9010\u6761\u4fdd\u5b58\uff0c\u9047\u9519\u505c\u6b62\u5e76\u62a5\u544a\u5df2\u4fdd\u5b58\u6570\u91cf\u3002</p><button type=\"submit\" class=\"primary\">\u6821\u9a8c\u5e76\u5bfc\u5165</button></fieldset></form></details></section>\n"
    "<section id=\"page-device\" aria-labelledby=\"deviceTitle\" hidden><h2 id=\"deviceTitle\">\u8bbe\u5907</h2><div class=\"panel\"><h3>\u65f6\u95f4\u6821\u51c6</h3><dl><dt>\u6d4f\u89c8\u5668\u65f6\u95f4</dt><dd id=\"browserTime\">--</dd><dt>\u8bbe\u5907\u65f6\u95f4</dt><dd id=\"deviceTime\">--</dd><dt>\u65f6\u95f4\u504f\u5dee</dt><dd id=\"drift\">--</dd></dl><p class=\"hint\">\u6bcf\u6b21\u540c\u6b65\u4f1a\u6d4b\u91cf\u591a\u8f6e\u5ef6\u8fdf\uff0c\u91c7\u7528\u8f83\u7a33\u5b9a\u7684\u6837\u672c\uff1b\u8bf7\u4fdd\u6301\u9875\u9762\u5728\u524d\u53f0\u3002\u624b\u673a\u81ea\u8eab\u65f6\u95f4\u9700\u51c6\u786e\uff0c\u5b8c\u5168\u65ad\u7535\u540e\u8bf7\u91cd\u65b0\u6821\u65f6\u3002\u65f6\u533a\u53ea\u5f71\u54cd\u663e\u793a\u3002</p><button type=\"button\" class=\"primary\" id=\"syncTime\" data-control>\u540c\u6b65\u5f53\u524d\u65f6\u95f4</button></div><div class=\"panel\"><h3>\u663e\u793a\u4e0e\u58f0\u97f3</h3><fieldset id=\"deviceFields\" disabled><label for=\"brightness\">\u4eae\u5ea6 <output id=\"brightnessValue\">80%</output></label><input id=\"brightness\" type=\"range\" min=\"10\" max=\"100\" value=\"80\"><label class=\"row\" for=\"sound\"><input id=\"sound\" type=\"checkbox\">\u6309\u952e\u58f0\u97f3</label></fieldset></div><div class=\"panel\"><h3>\u8bbe\u5907\u72b6\u6001</h3><dl><dt>\u82af\u7247\u6807\u8bc6</dt><dd id=\"deviceId\">--</dd><dt>\u70ed\u70b9\u540d\u79f0</dt><dd id=\"ssid\">--</dd><dt>\u7a7a\u95f2\u5185\u90e8\u5806</dt><dd id=\"heap\">--</dd><dt>\u6700\u5927\u8fde\u7eed\u5757</dt><dd id=\"largest\">--</dd></dl><p class=\"hint\">\u70ed\u70b9\u5bc6\u7801\u7531\u82af\u7247\u6807\u8bc6\u6d3e\u751f\uff0c\u540e\u56db\u4f4d\u5305\u542b\u5728 SSID \u4e2d\u3002\u8fd9\u662f\u4fbf\u6377\u914d\u7f51\u65b9\u6848\uff0c\u4e0d\u5e94\u5f53\u4f5c\u9ad8\u5f3a\u5ea6\u8eab\u4efd\u8ba4\u8bc1\u3002</p></div><div class=\"panel\"><h3>\u5371\u9669\u64cd\u4f5c</h3><p class=\"hint\">\u6e05\u7a7a\u4f1a\u5220\u9664\u8bbe\u5907\u4e0a\u7684 TOTP \u4e0e FIDO \u51ed\u636e\uff0c\u4e0d\u80fd\u64a4\u9500\u3002\u7f51\u9875\u53ea\u53d1\u8d77\u8bf7\u6c42\uff0c\u4ecd\u9700\u5728\u8bbe\u5907\u4e0a\u6309 OK \u786e\u8ba4\u3002</p><button type=\"button\" class=\"danger\" id=\"wipe\" data-control>\u8bf7\u6c42\u6e05\u7a7a\u5168\u90e8\u4ee4\u724c</button></div></section>\n"
    "<section id=\"page-lab\" aria-labelledby=\"labTitle\" hidden><h2 id=\"labTitle\">\u5b9e\u9a8c\u5ba4</h2><div class=\"panel\"><h3>RTC \u6821\u51c6\u5386\u53f2</h3><p class=\"hint\">\u53ea\u8bfb\u8bca\u65ad\uff1b\u5f71\u5b50\u4f30\u8ba1 READY \u4e0d\u4ee3\u8868\u542f\u7528\u3002\u6e29\u5ea6\u4e3a\u6e05\u9192\u7aef\u70b9\uff0c\u7535\u6c60\u7535\u538b\u4e0d\u4ee3\u8868 USB \u4f9b\u7535\u3002\u5237\u65b0\u4ec5\u663e\u793a\u524d 5 \u884c\uff1b\u5bfc\u51fa\u6700\u591a 100 \u884c\uff0c\u5386\u53f2\u53d8\u5316\u6216\u8bf7\u6c42\u5931\u8d25\u65f6\u4e0d\u4f1a\u4e0b\u8f7d\u90e8\u5206\u7ed3\u679c\u3002</p><div class=\"row\"><button type=\"button\" id=\"rtcRefresh\" data-control>\u67e5\u770b / \u5237\u65b0</button><button type=\"button\" id=\"rtcExport\" data-control>\u5bfc\u51fa\u6821\u51c6 JSON</button></div><p id=\"rtcSummary\" role=\"status\">\u89e3\u9501\u540e\u624b\u52a8\u5237\u65b0\uff1b\u4e0d\u4f1a\u81ea\u52a8\u6821\u65f6\u6216\u8f6e\u8be2\u5386\u53f2\u3002</p><pre id=\"rtcRows\" style=\"overflow:auto;max-height:320px\"></pre></div><div class=\"panel\"><h3>BLE FIDO</h3><p>\u4ece\u8bbe\u5907\u7684 Settings \u2192 Lab / Experiments \u5f00\u542f\uff0c\u9ed8\u8ba4\u5173\u95ed\u3002Wi-Fi \u70ed\u70b9\u8fd0\u884c\u65f6 BLE \u6682\u505c\uff0c\u4ee5\u63a7\u5236\u5185\u90e8 RAM \u4f7f\u7528\u3002</p><p class=\"hint\">BLE FIDO \u5c1a\u672a\u5b8c\u6210\u624b\u673a\u6ce8\u518c / \u767b\u5f55\u7aef\u5230\u7aef\u9a8c\u6536\uff0c\u4e0d\u80fd\u89c6\u4e3a\u5df2\u8ba4\u8bc1\u5b89\u5168\u5bc6\u94a5\u3002\u6b64\u9875\u4e0d\u5c06\u666e\u901a\u786e\u8ba4\u63d0\u793a\u5192\u5145 WebAuthn \u6ce8\u518c\u6210\u529f\u3002</p></div><div class=\"panel\"><h3>\u8c03\u8bd5\u8fb9\u754c</h3><p class=\"hint\">USB Log Console \u4ec5\u5207\u6362\u5e94\u7528\u65e5\u5fd7\uff0c\u4e0d\u5173\u95ed\u786c\u4ef6 JTAG\u3002\u672c\u56fa\u4ef6\u4e0d\u70e7\u5199 OTP/eFuse\uff0c\u4e5f\u4e0d\u542f\u7528\u4e0d\u53ef\u9006\u4fdd\u62a4\u3002ESP32-C3 \u7684\u56fa\u5b9a USB Serial/JTAG \u4e0d\u80fd\u63d0\u4f9b\u539f\u751f USB HID FIDO2\u3002</p></div></section>\n"
    "<footer>\u4ec5\u8fde\u63a5\u672c\u673a\u7ba1\u7406\uff0c\u4e0d\u4f9d\u8d56\u4e91\u670d\u52a1\u6216 CDN\u3002\u8bf7\u4fdd\u7559\u5404\u670d\u52a1\u7684\u6062\u590d\u7801\uff1b\u5f53\u524d\u56fa\u4ef6\u4e0d\u662f\u5b89\u5168\u82af\u7247\u6216\u8ba4\u8bc1\u8fc7\u7684\u5546\u4e1a\u5b89\u5168\u5bc6\u94a5\u3002</footer>\n"
    "</main>\n"
    "<script>\n"
    "'use strict';\n"
    "const $ = id => document.getElementById(id);\n"
    "const algorithms = ['SHA-1', 'SHA-256', 'SHA-512', 'Steam'];\n"
    "let status = null, accounts = [], editing = null, editingRevision = 0, accountRevision = 0, busy = false, connected = false;\n"
    "function message(text, error = false) { $('error').textContent = error ? text : ''; $('notice').textContent = error ? '' : text; }\n"
    "function controls() {\n"
    "  const enabled = connected && status && status.unlocked && !busy;\n"
    "  ['accountFields', 'importFields', 'deviceFields'].forEach(id => $(id).disabled = !enabled);\n"
    "  document.querySelectorAll('[data-control], #accountList button').forEach(el => el.disabled = !enabled);\n"
    "  const steam = $('algorithm').value === '3';\n"
    "  $('digits').disabled = !enabled || steam; $('period').disabled = !enabled || steam;\n"
    "}\n"
    "async function request(path, options, timeoutMs = 5000) {\n"
    "  const controller = typeof AbortController === 'function' ? new AbortController() : null;\n"
    "  let timer;\n"
    "  const deadline = new Promise((_,reject) => {\n"
    "    timer = setTimeout(() => { controller?.abort(); reject(new Error('\u8bf7\u6c42\u8d85\u65f6\uff0c\u8bf7\u91cd\u8bd5')); }, timeoutMs);\n"
    "  });\n"
    "  try {\n"
    "    return await Promise.race([(async () => {\n"
    "      const response = await fetch(path, {cache:'no-store', ...options, signal:controller?.signal});\n"
    "      if (!response.ok) {\n"
    "        const error = new Error(await response.text() || `\u8bf7\u6c42\u5931\u8d25 (${response.status})`);\n"
    "        error.status = response.status; throw error;\n"
    "      }\n"
    "      return response.json();\n"
    "    })(),deadline]);\n"
    "  } finally { clearTimeout(timer); }\n"
    "}\n"
    "async function updateStatus() {\n"
    "  status = await request('/api/status'); connected = true;\n"
    "  $('connection').textContent = '\u5df2\u8fde\u63a5 \u00b7 Wi-Fi'; $('connection').className = 'connected';\n"
    "  $('identity').textContent = `\u8bbe\u5907 ${status.device_id}`;\n"
    "  $('lockState').textContent = status.unlocked ? '\u8bbe\u5907\u5df2\u89e3\u9501' : '\u8bbe\u5907\u5df2\u9501\u5b9a\uff0c\u8bf7\u5148\u5728\u8bbe\u5907\u4e0a\u89e3\u9501';\n"
    "  $('deviceId').textContent = status.device_id; $('ssid').textContent = status.ssid;\n"
    "  $('heap').textContent = `${(status.heap / 1024).toFixed(1)} KiB`;\n"
    "  $('largest').textContent = `${(status.largest_block / 1024).toFixed(1)} KiB`;\n"
    "  $('deviceTime').textContent = status.time >= 1704067200 ? new Date(status.time * 1000).toLocaleString() : '\u5c1a\u672a\u6821\u65f6';\n"
    "  $('drift').textContent = status.time < 1577836800 ? '\u9700\u8981\u6821\u65f6' : `\u7ea6 ${Math.round(Date.now() / 1000 - status.time)} \u79d2\uff08\u6d4f\u89c8\u5668 \u2212 \u8bbe\u5907\uff09`;\n"
    "  if (!busy) { $('brightness').value = status.brightness; $('brightnessValue').textContent = `${status.brightness}%`; $('sound').checked = status.sound; }\n"
    "  if (!status.unlocked) { accounts = []; renderAccounts(); }\n"
    "  controls(); return status;\n"
    "}\n"
    "async function loadAccounts() {\n"
    "  if (!connected || !status?.unlocked) { accounts = []; renderAccounts(); return; }\n"
    "  const data = await request('/api/accounts'); accounts = data.accounts; accountRevision = data.revision; renderAccounts();\n"
    "}\n"
    "function renderAccounts() {\n"
    "  const list = $('accountList'); list.replaceChildren(); $('count').textContent = `${accounts.length} / 16`;\n"
    "  const query = $('search').value.trim().toLocaleLowerCase();\n"
    "  const visible = accounts.filter(a => `${a.issuer} ${a.account}`.toLocaleLowerCase().includes(query));\n"
    "  if (!visible.length) { const empty = document.createElement('div'); empty.className = 'empty'; empty.textContent = !connected ? '\u8fde\u63a5\u8bbe\u5907\u70ed\u70b9\u540e\u5237\u65b0\u672c\u9875' : !status?.unlocked ? '\u8bf7\u5148\u5728\u8bbe\u5907\u4e0a\u89e3\u9501' : accounts.length ? '\u6ca1\u6709\u5339\u914d\u7684\u8d26\u53f7' : '\u6682\u65e0\u4ee4\u724c\uff0c\u4ece\u4e0b\u65b9\u6dfb\u52a0\u6216\u5bfc\u5165'; list.append(empty); return; }\n"
    "  for (const a of visible) {\n"
    "    const row = document.createElement('div'); row.className = 'token';\n"
    "    const names = document.createElement('div'); names.className = 'names';\n"
    "    const issuer = document.createElement('strong'); issuer.textContent = a.issuer;\n"
    "    const account = document.createElement('small'); account.textContent = a.account;\n"
    "    const meta = document.createElement('div'); meta.className = 'meta'; meta.textContent = `${algorithms[a.algorithm] || '\u672a\u77e5\u7b97\u6cd5'} \u00b7 ${a.digits === 5 ? '5 \u5b57\u7b26' : a.digits + ' \u4f4d'} \u00b7 ${a.period} \u79d2`;\n"
    "    names.append(issuer, account, meta);\n"
    "    const rowRevision = accountRevision;\n"
    "    const actions = document.createElement('div'); actions.className = 'actions';\n"
    "    const edit = document.createElement('button'); edit.type = 'button'; edit.textContent = '\u7f16\u8f91'; edit.disabled = busy;\n"
    "    edit.addEventListener('click', () => editAccount(a));\n"
    "    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '\u5220\u9664'; remove.className = 'danger'; remove.disabled = busy;\n"
    "    remove.addEventListener('click', async () => { if (confirm(`\u5220\u9664 ${a.issuer} / ${a.account}\uff1f\u6b64\u64cd\u4f5c\u4e0d\u80fd\u64a4\u9500\u3002`)) { try { await sendCommand({command:'DEL_TOTP',index:a.index,revision:rowRevision}); message('\u4ee4\u724c\u5df2\u5220\u9664'); } catch(e) { message(e.message,true); } } });\n"
    "    actions.append(edit, remove); row.append(names, actions); list.append(row);\n"
    "  }\n"
    "}\n"
    "async function sendCommand(payload, alreadyBusy = false) {\n"
    "  if ((busy && !alreadyBusy) || !connected || !status?.unlocked) throw new Error('\u8bf7\u5148\u8fde\u63a5\u5e76\u5728\u8bbe\u5907\u4e0a\u89e3\u9501');\n"
    "  busy = true; controls(); renderAccounts();\n"
    "  try {\n"
    "    const result = await request('/api/command', {method:'POST', headers:{'Content-Type':'application/json','X-Passport-Session':status.session}, body:JSON.stringify({...payload,revision:payload.revision ?? accountRevision})});\n"
    "    const now = typeof performance !== 'undefined' && typeof performance.now === 'function' ? () => performance.now() : () => Date.now();\n"
    "    const deadline = now() + 6000;\n"
    "    while (now() < deadline) {\n"
    "      await new Promise(resolve => setTimeout(resolve, 200));\n"
    "      const current = await updateStatus();\n"
    "      const done = current.results.find(r => r.id === result.id);\n"
    "      if (done) { if (!done.ok) throw new Error('\u8bbe\u5907\u672a\u4fdd\u5b58\u64cd\u4f5c\uff0c\u53ef\u80fd\u5df2\u9501\u5b9a\u3001\u5b58\u50a8\u5931\u8d25\u6216\u53c2\u6570\u4e0d\u9002\u7528\uff1b\u8bf7\u5237\u65b0\u68c0\u67e5'); await loadAccounts(); return; }\n"
    "    }\n"
    "    throw new Error('\u64cd\u4f5c\u7ed3\u679c\u672a\u786e\u8ba4\uff0c\u8bf7\u5237\u65b0\u68c0\u67e5\uff0c\u4e0d\u8981\u8fde\u7eed\u91cd\u590d\u63d0\u4ea4');\n"
    "  } finally { if (!alreadyBusy) { busy = false; controls(); renderAccounts(); } }\n"
    "}\n"
    "function resetEditor() { editing = null; $('accountForm').reset(); $('editorTitle').textContent = '\u6dfb\u52a0\u4ee4\u724c'; $('secret').value = ''; applyAlgorithm(false); }\n"
    "function editAccount(a) {\n"
    "  editing = a.index; editingRevision = accountRevision; $('issuer').value = a.issuer; $('account').value = a.account; $('algorithm').value = a.algorithm;\n"
    "  $('digits').value = a.digits; $('period').value = a.period; $('encoding').value = 'base32'; $('secret').value = '';\n"
    "  $('editorTitle').textContent = '\u7f16\u8f91\u4ee4\u724c \u00b7 \u7559\u7a7a\u5bc6\u94a5\u8868\u793a\u4fdd\u7559'; $('accountEditor').open = true; applyAlgorithm(false); $('issuer').focus();\n"
    "}\n"
    "function applyAlgorithm(changeEncoding) {\n"
    "  const steam = $('algorithm').value === '3';\n"
    "  $('digits').querySelector('[value=\"5\"]').hidden = !steam;\n"
    "  if (steam) { $('digits').value = '5'; $('period').value = 30; if (changeEncoding) $('encoding').value = 'base64'; }\n"
    "  else { if ($('digits').value === '5') $('digits').value = '6'; if (changeEncoding) $('encoding').value = 'base32'; }\n"
    "  controls();\n"
    "}\n"
    "function base64ToBase32(value) {\n"
    "  let raw; try { raw = atob(value.replace(/\\s/g,'')); } catch { throw new Error('shared_secret \u4e0d\u662f\u6709\u6548 Base64'); }\n"
    "  if (!raw.length || raw.length > 64) throw new Error('shared_secret \u957f\u5ea6\u4e0d\u9002\u7528');\n"
    "  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'; let bits = 0, buffer = 0, result = '';\n"
    "  for (const ch of raw) { buffer = ((buffer << 8) | ch.charCodeAt(0)) >>> 0; bits += 8; while (bits >= 5) { bits -= 5; result += alphabet[(buffer >>> bits) & 31]; } }\n"
    "  if (bits) result += alphabet[(buffer << (5 - bits)) & 31];\n"
    "  return result;\n"
    "}\n"
    "function validateAccount(a, allowEmptySecret = false) {\n"
    "  const bytes = value => new TextEncoder().encode(value).length;\n"
    "  if (!a.issuer || !a.account || bytes(a.issuer) > 31 || bytes(a.account) > 31 || /[\\x00-\\x1f]/.test(a.issuer + a.account)) throw new Error('\u670d\u52a1\u5546\u4e0e\u8d26\u53f7\u5fc5\u586b\uff0c\u5404\u6700\u591a 31 \u5b57\u8282\uff0c\u4e0d\u80fd\u542b\u63a7\u5236\u5b57\u7b26');\n"
    "  if ((!a.secret && !allowEmptySecret) || a.secret.length > 127 || (a.secret && !/^[A-Z2-7]+=*$/.test(a.secret))) throw new Error('\u8bf7\u8f93\u5165\u6709\u6548 Base32 \u5bc6\u94a5\uff08\u6700\u957f 127 \u5b57\u7b26\uff09');\n"
    "  if (!Number.isInteger(a.period) || a.period < 1 || a.period > 255 || !Number.isInteger(a.algorithm) || a.algorithm < 0 || a.algorithm > 3) throw new Error('\u7b97\u6cd5\u6216\u5237\u65b0\u5468\u671f\u4e0d\u6b63\u786e');\n"
    "  if (a.algorithm === 3 ? (a.digits !== 5 || a.period !== 30) : ![6,8].includes(a.digits)) throw new Error('TOTP \u652f\u6301 6/8 \u4f4d\uff1bSteam \u56fa\u5b9a 5 \u5b57\u7b26\u300130 \u79d2');\n"
    "  return a;\n"
    "}\n"
    "function parseOtpUri(line) {\n"
    "  let uri; try { uri = new URL(line); } catch { throw new Error('\u94fe\u63a5\u683c\u5f0f\u4e0d\u6b63\u786e'); }\n"
    "  if (uri.protocol !== 'otpauth:' || uri.hostname !== 'totp') throw new Error('\u4ec5\u652f\u6301 otpauth://totp/ \u94fe\u63a5\uff0c\u4e0d\u652f\u6301 HOTP');\n"
    "  let label; try { label = decodeURIComponent(uri.pathname.slice(1)); } catch { throw new Error('\u8d26\u53f7\u540d\u79f0\u7f16\u7801\u4e0d\u6b63\u786e'); }\n"
    "  const colon = label.indexOf(':'); const issuer = uri.searchParams.get('issuer') || (colon >= 0 ? label.slice(0,colon) : 'TOTP');\n"
    "  const account = colon >= 0 ? label.slice(colon + 1) : label;\n"
    "  const name = (uri.searchParams.get('algorithm') || 'SHA1').toUpperCase();\n"
    "  const steam = uri.searchParams.get('encoder')?.toLowerCase() === 'steam' || name === 'STEAM';\n"
    "  const algorithm = steam ? 3 : ['SHA1','SHA256','SHA512'].indexOf(name);\n"
    "  return validateAccount({issuer,account,secret:(uri.searchParams.get('secret') || '').replace(/[\\s-]/g,'').toUpperCase(),algorithm,digits:steam ? 5 : Number(uri.searchParams.get('digits') || 6),period:steam ? 30 : Number(uri.searchParams.get('period') || 30)});\n"
    "}\n"
    "$('accountForm').addEventListener('submit', async e => {\n"
    "  e.preventDefault(); try {\n"
    "    let secret = $('secret').value.trim();\n"
    "    if (secret) secret = $('encoding').value === 'base64' ? base64ToBase32(secret) : secret.replace(/[\\s-]/g,'').toUpperCase();\n"
    "    const payload = validateAccount({issuer:$('issuer').value.trim(),account:$('account').value.trim(),secret,algorithm:Number($('algorithm').value),digits:Number($('digits').value),period:Number($('period').value)},editing !== null);\n"
    "    if (editing === null && accounts.length >= 16) throw new Error('\u8bbe\u5907\u6700\u591a\u4fdd\u5b58 16 \u4e2a\u4ee4\u724c\uff0c\u8bf7\u5148\u5220\u9664\u4e0d\u9700\u8981\u7684\u8d26\u53f7');\n"
    "    await sendCommand({...payload,command:editing === null ? 'ADD_TOTP':'EDIT_TOTP',...(editing === null ? {}:{index:editing,revision:editingRevision})});\n"
    "    resetEditor(); message('\u4ee4\u724c\u5df2\u4fdd\u5b58');\n"
    "  } catch(e) { message(e.message,true); }\n"
    "});\n"
    "$('importForm').addEventListener('submit', async e => {\n"
    "  e.preventDefault(); let saved = 0;\n"
    "  try {\n"
    "    const lines = $('uris').value.split(/\\r?\\n/).map(s => s.trim()).filter(Boolean);\n"
    "    if (!lines.length || lines.length + accounts.length > 16) throw new Error('\u5bfc\u5165\u5185\u5bb9\u4e3a\u7a7a\u6216\u8d85\u51fa 16 \u4e2a\u4ee4\u724c\u4e0a\u9650');\n"
    "    const parsed = lines.map((line,i) => { try { return parseOtpUri(line); } catch(e) { throw new Error(`\u7b2c ${i+1} \u6761\uff1a${e.message}`); } });\n"
    "    for (const a of parsed) { await sendCommand({...a,command:'ADD_TOTP'}); saved++; }\n"
    "    $('uris').value = ''; message(`\u5df2\u5bfc\u5165 ${saved} \u4e2a\u4ee4\u724c`);\n"
    "  } catch(e) { message(`\u5df2\u4fdd\u5b58 ${saved} \u4e2a\uff1b${e.message}`,true); }\n"
    "});\n"
    "$('algorithm').addEventListener('change', () => applyAlgorithm(true));\n"
    "$('cancelEdit').addEventListener('click', resetEditor);\n"
    "$('search').addEventListener('input', renderAccounts);\n"
    "$('refresh').addEventListener('click', async () => { try { await updateStatus(); await loadAccounts(); message('\u8d26\u53f7\u5df2\u5237\u65b0'); } catch(e) { message(e.message,true); } });\n"
    "function rtcDecimal(value) {\n"
    "  if (typeof value !== 'string' || !/^(0|[1-9][0-9]{0,19})$/.test(value) || (value.length === 20 && value > '18446744073709551615')) throw new Error('\u6821\u51c6\u6574\u6570\u683c\u5f0f\u9519\u8bef\uff0c\u8bf7\u5237\u65b0');\n"
    "  return value;\n"
    "}\n"
    "function rtcPick(input, decimalKeys, numberKeys, boolKeys = []) {\n"
    "  if (!input || typeof input !== 'object') throw new Error('\u6821\u51c6\u6570\u636e\u7f3a\u5931');\n"
    "  const output = {};\n"
    "  for (const key of decimalKeys) output[key] = rtcDecimal(input[key]);\n"
    "  for (const key of numberKeys) {\n"
    "    if (typeof input[key] !== 'number' || !Number.isFinite(input[key])) throw new Error('\u6821\u51c6\u6570\u503c\u65e0\u6548');\n"
    "    output[key] = input[key];\n"
    "  }\n"
    "  for (const key of boolKeys) {\n"
    "    if (typeof input[key] !== 'boolean') throw new Error('\u6821\u51c6\u6709\u6548\u6027\u6807\u8bb0\u7f3a\u5931');\n"
    "    output[key] = input[key];\n"
    "  }\n"
    "  return output;\n"
    "}\n"
    "function rtcSummaryOnly(input) {\n"
    "  const summary = rtcPick(input, ['accepted_sequence','durable_sequence','dropped','save_budget_us'],\n"
    "    ['durable_count','pending_count','flags','store_status','save_result','active_ppm','legacy_candidate_ppm','learning_reason'],\n"
    "    ['ready','active_qualified','legacy_candidate_qualified']);\n"
    "  summary.shadow = rtcPick(input.shadow, [], ['version','source','result','samples','inliers','excluded','ppm','uncertainty_ppm','holdout_baseline_error_us','holdout_candidate_error_us'], ['holdout_present','holdout_improved']);\n"
    "  return summary;\n"
    "}\n"
    "function rtcRowOnly(input) {\n"
    "  return rtcPick(input, ['sequence','utc_end_us','raw_us','awake_delta_us','utc_delta_us','combined_uncertainty_us'],\n"
    "    ['source','raw_fraction_q19','flags','temperature_centi_c','battery_mv','temp_age_s','battery_age_s']);\n"
    "}\n"
    "async function readRtcHistory(allPages) {\n"
    "  if (!connected || !status?.unlocked) throw new Error('\u8bf7\u5148\u8fde\u63a5\u5e76\u5728\u8bbe\u5907\u4e0a\u89e3\u9501');\n"
    "  const session = status.session;\n"
    "  let generation, total, summary, cursor = 0;\n"
    "  const rows = [];\n"
    "  const checkAccess = () => { if (!connected || !status?.unlocked || status.session !== session) throw new Error('\u8bbe\u5907\u9501\u5b9a\u6216\u4f1a\u8bdd\u5df2\u53d8\u5316\uff0c\u8bf7\u5237\u65b0'); };\n"
    "  for (let pageNumber = 0; pageNumber < 20; ++pageNumber) {\n"
    "    checkAccess();\n"
    "    const page = await request('/api/rtc-history?cursor=' + cursor + (generation === undefined ? '' : '&generation=' + generation), {headers:{'X-Passport-Session':session}});\n"
    "    checkAccess();\n"
    "    const currentGeneration = rtcDecimal(page.generation);\n"
    "    if (generation !== undefined && (currentGeneration !== generation || page.total !== total)) throw new Error('\u5386\u53f2\u5df2\u53d8\u5316\uff0c\u8bf7\u91cd\u65b0\u5237\u65b0\uff1b\u672a\u5bfc\u51fa\u90e8\u5206\u7ed3\u679c');\n"
    "    if (!Number.isInteger(page.total) || page.total < 0 || page.total > 100 || page.cursor !== cursor || !Array.isArray(page.rows) ||\n"
    "        page.rows.length !== Math.min(5, page.total - cursor) || page.next_cursor !== cursor + page.rows.length) throw new Error('\u5386\u53f2\u5206\u9875\u8d8a\u754c\u6216\u4e0d\u5b8c\u6574');\n"
    "    const currentSummary = rtcSummaryOnly(page.summary);\n"
    "    if (!currentSummary.ready) throw new Error('\u5386\u53f2\u5c1a\u672a\u5c31\u7eea');\n"
    "    if (generation === undefined) { generation = currentGeneration; total = page.total; summary = currentSummary; }\n"
    "    rows.push(...page.rows.map(rtcRowOnly));\n"
    "    cursor = page.next_cursor;\n"
    "    if (!allPages || cursor === total) return {schema:1,generation,total,summary,rows};\n"
    "  }\n"
    "  throw new Error('\u5386\u53f2\u8d85\u51fa 20 \u9875\uff1b\u672a\u5bfc\u51fa\u90e8\u5206\u7ed3\u679c');\n"
    "}\n"
    "function renderRtcHistory(data) {\n"
    "  const s = data.summary;\n"
    "  const reasons = {0:'\u62d2\u7edd\uff1a\u65e0\u6548\u53c2\u8003',1:'\u57fa\u7ebf\u5df2\u8bb0\u5f55',2:'\u91cd\u590d\u53c2\u8003',3:'\u7761\u7720\u8bc1\u636e\u4e0d\u8db3',4:'\u62d2\u7edd\uff1a\u533a\u95f4\u65e0\u6548',5:'\u62d2\u7edd\uff1a\u901f\u7387\u8d8a\u754c',6:'\u62d2\u7edd\uff1a\u4e0d\u786e\u5b9a\u6027\u8fc7\u5927',7:'\u5019\u9009\u5f85\u786e\u8ba4',8:'\u62d2\u7edd\uff1a\u8bc1\u636e\u4e0d\u4e00\u81f4',9:'\u5df2\u53d1\u5e03',10:'\u62d2\u7edd\uff1a\u65f6\u949f\u6e90\u53d8\u5316',11:'\u62d2\u7edd\uff1a\u8fde\u7eed\u6027\u53d8\u5316',12:'\u62d2\u7edd\uff1a\u6ea2\u51fa',13:'\u65e0\u65b0\u589e\u7761\u7720\u8bc1\u636e\uff08\u6e05\u9192\u671f\u95f4\u91cd\u590d\u6821\u65f6\u4e0d\u4f1a\u66ff\u6362\u5f85\u786e\u8ba4\u5019\u9009\uff09'};\n"
    "  $('rtcSummary').textContent = `\u5f53\u524d\u5df2\u53d1\u5e03\u7cfb\u6570 ${s.active_ppm} ppm\uff08${s.active_qualified ? '\u5408\u683c' : '\u672a\u5408\u683c'}\uff09\uff1b\u65e7\u5b66\u4e60\u5019\u9009 ${s.legacy_candidate_ppm} ppm\uff08${s.legacy_candidate_qualified ? '\u5408\u683c' : '\u5f85\u786e\u8ba4'}\uff09\uff1b${reasons[s.learning_reason] || '\u672a\u77e5\u5b66\u4e60\u7ed3\u679c'}\u3002\u5df2\u63a5\u7eb3\u5e8f\u53f7 ${s.accepted_sequence} / \u5df2\u6301\u4e45\u5316 ${s.durable_sequence}\uff1b\u5f85\u4fdd\u5b58 ${s.pending_count}\uff1b${s.accepted_sequence !== s.durable_sequence || s.pending_count ? '\u672a\u6301\u4e45\u5316\uff0c\u7acb\u5373\u65ad\u7535\u53ef\u80fd\u4e22\u5931' : '\u5df2\u6301\u4e45\u5316'}\uff1b\u4e22\u5f03 ${s.dropped}\uff1b\u5b58\u50a8\u72b6\u6001 ${s.store_status} / \u4fdd\u5b58\u7ed3\u679c ${s.save_result}\u3002\u5f71\u5b50\u4f30\u8ba1 ${['PENDING','INCONSISTENT','READY'][s.shadow.result] || '\u672a\u77e5'}\uff08\u4ec5\u8bca\u65ad\uff0c\u672a\u6fc0\u6d3b\uff09\uff1a${s.shadow.ppm} ppm\u3002\u663e\u793a ${data.rows.length} / ${data.total} \u884c\u3002`;\n"
    "  $('rtcRows').textContent = JSON.stringify(data.rows, null, 2);\n"
    "}\n"
    "async function rtcHistoryAction(download) {\n"
    "  if (busy) return;\n"
    "  busy = true; controls();\n"
    "  $('rtcRows').textContent = ''; $('rtcSummary').textContent = '\u8bfb\u53d6\u6821\u51c6\u5386\u53f2\u2026';\n"
    "  try {\n"
    "    const data = await readRtcHistory(download);\n"
    "    renderRtcHistory(data);\n"
    "    if (download) {\n"
    "      const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], {type:'application/json'}));\n"
    "      try { const link = document.createElement('a'); link.href = url; link.download = 'rtc-calibration.json'; link.click(); }\n"
    "      finally { URL.revokeObjectURL(url); }\n"
    "      message('\u6821\u51c6\u5386\u53f2\u5b8c\u6574\u5bfc\u51fa\uff1b\u4e0d\u542b\u8d26\u53f7\u3001\u8bbe\u5907\u6807\u8bc6\u6216\u4f1a\u8bdd\u51ed\u636e');\n"
    "    }\n"
    "  } catch(e) { $('rtcRows').textContent = ''; $('rtcSummary').textContent = '\u8bfb\u53d6\u5931\u8d25\uff1b\u6ca1\u6709\u4e0b\u8f7d\u90e8\u5206\u5386\u53f2\uff0c\u8bf7\u5237\u65b0\u91cd\u8bd5\u3002'; message(e.message,true); }\n"
    "  finally { busy = false; controls(); }\n"
    "}\n"
    "$('rtcRefresh').addEventListener('click', () => rtcHistoryAction(false));\n"
    "$('rtcExport').addEventListener('click', () => rtcHistoryAction(true));\n"
    "function timeSyncSample({probe,wallBeforeMs,wallAfterMs,monoBeforeMs,monoAfterMs}) {\n"
    "  const rttMs = monoAfterMs - monoBeforeMs;\n"
    "  if (![wallBeforeMs,wallAfterMs,monoBeforeMs,monoAfterMs,rttMs].every(Number.isFinite) || rttMs <= 0 || rttMs > 500) return null;\n"
    "  if (Math.abs(wallAfterMs - wallBeforeMs - rttMs) > 5) throw new Error('\u624b\u673a\u65f6\u95f4\u53d1\u751f\u53d8\u5316\uff0c\u8bf7\u7a33\u5b9a\u540e\u91cd\u65b0\u6821\u65f6');\n"
    "  if (!probe || probe.version !== 2 || probe.valid !== true ||\n"
    "      !Number.isInteger(probe.id) || probe.id <= 0 || probe.id > 0xffffffff ||\n"
    "      !Number.isSafeInteger(probe.received_us) || probe.received_us < 0 ||\n"
    "      !Number.isSafeInteger(probe.sent_us) || probe.sent_us < probe.received_us) return null;\n"
    "  const processingUs = probe.sent_us - probe.received_us;\n"
    "  const rttUs = Math.ceil(rttMs * 1000);\n"
    "  if (processingUs > rttMs * 1000 || processingUs > 500000) return null;\n"
    "  const anchorUs = probe.received_us + Math.floor(processingUs / 2);\n"
    "  const offsetUs = wallBeforeMs * 1000 + rttMs * 500 - anchorUs;\n"
    "  if (!Number.isFinite(offsetUs) || wallBeforeMs < 1577836800000 || wallAfterMs > 4102444800000) return null;\n"
    "  return {probe,anchorUs,offsetUs,rttUs,networkUs:rttUs-processingUs,monoAfterMs};\n"
    "}\n"
    "function selectTimeSyncReference(samples) {\n"
    "  if (samples.length < 6) throw new Error('\u6709\u6548\u6821\u65f6\u6837\u672c\u4e0d\u8db3\uff0c\u8bf7\u4fdd\u6301\u9875\u9762\u5728\u524d\u53f0\u540e\u91cd\u8bd5');\n"
    "  const group = samples.map((s,index)=>({...s,index})).sort((a,b)=>a.networkUs-b.networkUs || a.index-b.index)\n"
    "    .slice(0,Math.min(5,Math.max(3,Math.ceil(samples.length/3))));\n"
    "  const offsets = group.map(s=>s.offsetUs).sort((a,b)=>a-b);\n"
    "  const center = Math.floor(offsets.length/2);\n"
    "  const medianUs = offsets.length%2 ? offsets[center] : (offsets[center-1]+offsets[center])/2;\n"
    "  const spreadUs = Math.ceil(Math.max(...offsets.map(value=>Math.abs(value-medianUs))));\n"
    "  if (spreadUs > 20000) throw new Error('\u6821\u65f6\u6837\u672c\u4e0d\u7a33\u5b9a\uff0c\u8bf7\u9760\u8fd1\u8bbe\u5907\u540e\u91cd\u8bd5');\n"
    "  const anchor = group.reduce((a,b)=>a.index>b.index?a:b);\n"
    "  const utcUs = Math.round(anchor.anchorUs+medianUs);\n"
    "  if (!Number.isSafeInteger(utcUs) || utcUs < 1577836800000000 || utcUs > 4102444800000000) throw new Error('\u624b\u673a\u65f6\u95f4\u8d85\u51fa\u652f\u6301\u8303\u56f4');\n"
    "  return {payload:{command:'SYNC_TIME',value:Math.floor(utcUs/1000000),reference_version:2,\n"
    "    reference_probe_id:anchor.probe.id,reference_utc_us:utcUs,\n"
    "    reference_rtt_us:anchor.rttUs,reference_spread_us:spreadUs},\n"
    "    transportUs:Math.ceil(anchor.networkUs/2)+1000+spreadUs,\n"
    "    networkUs:anchor.networkUs,samples:samples.length};\n"
    "}\n"
    "async function syncBrowserTime() {\n"
    "  let ownsBusy = false;\n"
    "  try {\n"
    "    if (busy || !connected || !status?.unlocked) throw new Error('\u8bf7\u5148\u8fde\u63a5\u5e76\u5728\u8bbe\u5907\u4e0a\u89e3\u9501');\n"
    "    if (typeof performance === 'undefined' || typeof performance.now !== 'function') throw new Error('\u6d4f\u89c8\u5668\u4e0d\u652f\u6301\u7cbe\u786e\u8ba1\u65f6\uff0c\u8bf7\u6362\u7528\u73b0\u4ee3\u6d4f\u89c8\u5668');\n"
    "    const session = status.session, device = status.device_id;\n"
    "    const checkSession = current => {\n"
    "      if (!current?.unlocked || !connected || current.session !== session || current.device_id !== device)\n"
    "        throw new Error('\u8bbe\u5907\u5df2\u9501\u5b9a\u6216\u8fde\u63a5\u5df2\u53d8\u5316\uff0c\u8bf7\u5237\u65b0\u540e\u91cd\u8bd5');\n"
    "    };\n"
    "    busy = true; ownsBusy = true; controls(); renderAccounts();\n"
    "    const fresh = await request('/api/status'); checkSession(fresh); status = fresh;\n"
    "    const startWall = Date.now(), startMono = performance.now();\n"
    "    const samples = [];\n"
    "    const checkClock = () => {\n"
    "      if (document.hidden) throw new Error('\u8bf7\u4fdd\u6301\u9875\u9762\u5728\u524d\u53f0\uff0c\u7136\u540e\u91cd\u65b0\u6821\u65f6');\n"
    "      if (Math.abs(Date.now()-startWall-(performance.now()-startMono)) > 5)\n"
    "        throw new Error('\u624b\u673a\u65f6\u95f4\u53d1\u751f\u53d8\u5316\uff0c\u8bf7\u7a33\u5b9a\u540e\u91cd\u65b0\u6821\u65f6');\n"
    "    };\n"
    "    for (let i=0;i<12;i++) {\n"
    "      checkSession(status); checkClock();\n"
    "      const remainingMs = 3000-(performance.now()-startMono);\n"
    "      if (remainingMs <= 0) break;\n"
    "      message(`\u6b63\u5728\u6d4b\u91cf\u6821\u65f6\u5ef6\u8fdf ${i+1}/12\uff0c\u8bf7\u4fdd\u6301\u9875\u9762\u5728\u524d\u53f0`);\n"
    "      const wallBeforeMs = Date.now(), monoBeforeMs = performance.now();\n"
    "      let probe;\n"
    "      try { probe = await request('/api/time-probe', {headers:{'X-Passport-Session':session}}, Math.min(500,remainingMs)); }\n"
    "      catch (error) { if (error.status === 403 || error.status === 423) throw error; continue; }\n"
    "      const monoAfterMs = performance.now(), wallAfterMs = Date.now();\n"
    "      checkSession(status); checkClock();\n"
    "      const sample = timeSyncSample({probe,wallBeforeMs,wallAfterMs,monoBeforeMs,monoAfterMs});\n"
    "      if (sample) samples.push(sample);\n"
    "    }\n"
    "    checkSession(status); checkClock();\n"
    "    const selected = selectTimeSyncReference(samples);\n"
    "    // Submit once. The owner advances this cached anchor to its actual execution time.\n"
    "    await sendCommand(selected.payload, true);\n"
    "    message(`\u65f6\u95f4\u540c\u6b65\u5df2\u5b8c\u6210\uff08${selected.samples} \u7ec4\u6709\u6548\u91c7\u6837\uff09\uff1b\u4f20\u8f93\u8bef\u5dee\u4f30\u8ba1 \u00b1${(selected.transportUs/1000).toFixed(1)} ms\u3002\u624b\u673a\u81ea\u8eab\u65f6\u95f4\u4ecd\u6309 \u00b11 \u79d2\u754c\u9650\u8ba1\u5165\uff0c\u4e0d\u4ee3\u8868\u5df2\u9a8c\u8bc1\u7edd\u5bf9\u7cbe\u5ea6\u3002`);\n"
    "  } catch(e) { message(e.message,true); }\n"
    "  finally { if (ownsBusy) { busy = false; controls(); renderAccounts(); } }\n"
    "}\n"
    "$('syncTime').addEventListener('click', syncBrowserTime);\n"
    "$('brightness').addEventListener('input', e => $('brightnessValue').textContent = `${e.target.value}%`);\n"
    "$('brightness').addEventListener('change', async e => { try { await sendCommand({command:'SET_BRIGHTNESS',value:Number(e.target.value)}); message('\u4eae\u5ea6\u5df2\u4fdd\u5b58'); } catch(e) { message(e.message,true); } });\n"
    "$('sound').addEventListener('change', async e => { try { await sendCommand({command:'SET_SOUND',value:e.target.checked ? 1:0}); message('\u58f0\u97f3\u8bbe\u7f6e\u5df2\u4fdd\u5b58'); } catch(e) { message(e.message,true); } });\n"
    "$('wipe').addEventListener('click', async () => { if (!confirm('\u8bf7\u6c42\u5220\u9664\u5168\u90e8 TOTP \u548c FIDO \u51ed\u636e\uff1f\u53d1\u9001\u540e\u8fd8\u9700\u8981\u5728\u8bbe\u5907\u4e0a\u6309 OK \u786e\u8ba4\u3002')) return; try { await sendCommand({command:'WIPE_ALL',confirm:true}); message('\u8bf7\u6c42\u5df2\u9001\u8fbe\uff0c\u8bf7\u5728\u8bbe\u5907\u4e0a\u6309 OK \u786e\u8ba4\uff1bUP/DOWN \u6216\u8fd4\u56de\u53d6\u6d88'); } catch(e) { message(e.message,true); } });\n"
    "document.querySelectorAll('[data-page]').forEach(button => button.addEventListener('click', () => {\n"
    "  document.querySelectorAll('[data-page]').forEach(b => b.setAttribute('aria-pressed',String(b === button)));\n"
    "  ['accounts','device','lab'].forEach(name => $('page-'+name).hidden = name !== button.dataset.page);\n"
    "}));\n"
    "async function poll() {\n"
    "  $('browserTime').textContent = new Date().toLocaleString();\n"
    "  if (!busy && !document.hidden) { try { const wasUnlocked = !!status?.unlocked, wasConnected = connected; await updateStatus(); if (status.unlocked && (!wasUnlocked || !wasConnected)) await loadAccounts(); } catch { connected = false; $('connection').textContent = '\u672a\u8fde\u63a5'; $('connection').className = ''; $('lockState').textContent = '\u8bf7\u8fde\u63a5\u8bbe\u5907\u70ed\u70b9\u5e76\u6253\u5f00 http://192.168.4.1'; controls(); } }\n"
    "  setTimeout(poll, document.hidden ? 3000 : 1000);\n"
    "}\n"
    "poll();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";
#define s_web_page_html_len (sizeof(s_web_page_html) - 1)
